from collections import Counter

def check(arr):
	l = len(arr)
	for i in range(len(arr)):
		if l - i - 1 > arr[i]:
			return False
	return True

def boredom(arr):
	arr = sorted(arr, reverse=True)
	for ans in range(1, len(arr) + 1):
		d = {}
		ind = 0
		for i in arr:
			d[ind] = d.get(ind, []) + [i]
			ind += 1
			ind %= ans
		flag = False
		for i in d.keys():
			if check(d[i]) == False:
				flag = True
				break
		if flag == False:
			return ans
